use nu_ansi_term :: { Color , Style } ; use reedline :: { Highlighter , StyledText } ; use super :: * ; # [doc = " Walk through `line` and emit styled segments, colouring every `@[...]`"] # [doc = " mention (matching the ZSH pattern `@\\[[^]]*\\]`) in cyan bold and leaving"] # [doc = " surrounding text unstyled."] # [doc = ""] # [doc = " Mirrors `ZSH_HIGHLIGHT_PATTERNS+=('@\\[[^]]#\\]' 'fg=cyan,bold')` exactly:"] # [doc = " - Requires `@[` opener."] # [doc = " - Matches zero or more non-`]` characters inside the brackets."] # [doc = " - Requires closing `]` — unterminated tags are left unstyled."] fn highlight_mentions (line : & str , styled : & mut StyledText) { let mut remaining = line ; while ! remaining . is_empty () { match remaining . find ("@[") { None => { styled . push ((Style :: new () , remaining . to_string ())) ; break ; } Some (start) => { if start > 0 && let Some (before) = remaining . get (.. start) { styled . push ((Style :: new () , before . to_string ())) ; } let after_open = match remaining . get (start ..) { Some (s) => s , None => { styled . push ((Style :: new () , remaining . to_string ())) ; break ; } } ; match after_open . get (2 ..) . and_then (| s | s . find (']')) { None => { styled . push ((Style :: new () , after_open . to_string ())) ; break ; } Some (rel_close) => { let close = 2 + rel_close ; let mention = after_open . get (..= close) . unwrap_or (after_open) ; styled . push ((Style :: new () . bold () . fg (Color :: Cyan) , mention . to_string ())) ; match after_open . get (close + 1 ..) { Some (rest) => remaining = rest , None => break , } } } } } } }